# figure-export.set: Change figure export settings
cellucid_figure_export_set <- function(viewer, auto_text_size, background, background_color, depth_sort, download, dpi, emphasize_selection, export_all_views, font_family, font_sizes, frame, include_axes, include_legend, legend_position, optimized_target_count, preview, reference_grid, selection_muted_opacity, show_orientation, size_preset, svg_strategy, title, title_follows_dataset, width, x_label, y_label) {
  params <- list()
  if (!missing(auto_text_size)) params["auto_text_size"] <- list(auto_text_size)
  if (!missing(background)) params["background"] <- list(background)
  if (!missing(background_color)) params["background_color"] <- list(background_color)
  if (!missing(depth_sort)) params["depth_sort"] <- list(depth_sort)
  if (!missing(download)) params["download"] <- list(download)
  if (!missing(dpi)) params["dpi"] <- list(dpi)
  if (!missing(emphasize_selection)) params["emphasize_selection"] <- list(emphasize_selection)
  if (!missing(export_all_views)) params["export_all_views"] <- list(export_all_views)
  if (!missing(font_family)) params["font_family"] <- list(font_family)
  if (!missing(font_sizes)) params["font_sizes"] <- list(font_sizes)
  if (!missing(frame)) params["frame"] <- list(frame)
  if (!missing(include_axes)) params["include_axes"] <- list(include_axes)
  if (!missing(include_legend)) params["include_legend"] <- list(include_legend)
  if (!missing(legend_position)) params["legend_position"] <- list(legend_position)
  if (!missing(optimized_target_count)) params["optimized_target_count"] <- list(optimized_target_count)
  if (!missing(preview)) params["preview"] <- list(preview)
  if (!missing(reference_grid)) params["reference_grid"] <- list(reference_grid)
  if (!missing(selection_muted_opacity)) params["selection_muted_opacity"] <- list(selection_muted_opacity)
  if (!missing(show_orientation)) params["show_orientation"] <- list(show_orientation)
  if (!missing(size_preset)) params["size_preset"] <- list(size_preset)
  if (!missing(svg_strategy)) params["svg_strategy"] <- list(svg_strategy)
  if (!missing(title)) params["title"] <- list(title)
  if (!missing(title_follows_dataset)) params["title_follows_dataset"] <- list(title_follows_dataset)
  if (!missing(width)) params["width"] <- list(width)
  if (!missing(x_label)) params["x_label"] <- list(x_label)
  if (!missing(y_label)) params["y_label"] <- list(y_label)
  .act(viewer, "figure-export.set", params, "cellucid_figure_export_set()")
}

