# vector-field.summary: Summarize where cells are heading
cellucid_vector_field_summary <- function(viewer, by, categories, neighbors = 30, vector_field, view, visible_only = FALSE) {
  if (missing(by)) .missing_action_param("cellucid_vector_field_summary", "by")
  params <- list(by = by)
  if (!missing(categories)) params["categories"] <- list(categories)
  if (!missing(neighbors)) params["neighbors"] <- list(neighbors)
  if (!missing(vector_field)) params["vector_field"] <- list(vector_field)
  if (!missing(view)) params["view"] <- list(view)
  if (!missing(visible_only)) params["visible_only"] <- list(visible_only)
  .act(viewer, "vector-field.summary", params, "cellucid_vector_field_summary()")
}

